test "d2b3d product facade rejects copied scratch and parser seal drift before publish" {
    const Apply = struct {
        fn run(
            _: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            return .applied;
        }
    };
    inline for (.{ false, true }) |drift_parser| {
