    };
    var guard = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const captured = ProductReplacementAllocationGuard.check(
        &guard,
        .capture_before_allocate,
