    };
    const alias_candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(scratch),
        .len = @sizeOf(ExternalRxTurnScratch),
    };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &alias_guard,
            .capture_after_allocate,
            alias_seal,
            alias_candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &alias_guard,
            .validate_allocated,
            alias_seal,
            alias_candidate,
        ) == .quarantined,
    );
}

test "C4d product replacement cleanup requires validated capture and seals abort and zero-cap commit" {
    const Helper = struct {
        fn advance(
            guard: *ProductReplacementAllocationGuard,
            candidate: client_external_mode.ReplacementCandidate,
        ) !client_external_mode.ReplacementAuthoritySeal {
            const captured = ProductReplacementAllocationGuard.check(
                guard,
                .capture_before_allocate,
                null,
                null,
            );
            const seal = switch (captured) {
                .seal => |value| value,
                else => return error.TestUnexpectedResult,
            };
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .capture_after_allocate,
                    seal,
                    candidate,
                ) == .seal,
            );
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .validate_allocated,
                    seal,
                    candidate,
                ) == .accepted,
            );
            return seal;
        }

        fn captureValidated(
            guard: *ProductReplacementAllocationGuard,
            seal: client_external_mode.ReplacementAuthoritySeal,
            candidate: client_external_mode.ReplacementCandidate,
        ) !void {
            try std.testing.expect(
                ProductReplacementAllocationGuard.check(
                    guard,
                    .capture_after_validate,
                    seal,
                    candidate,
                ) == .seal,
            );
        }
    };

    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    defer _ = teardownForTest(&storage);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var lease: ExternalWholeTurnLease = .{};
    try storage.acquireWholeTurnLease(
        &lease,
        @intFromPtr(scratch),
        @sizeOf(ExternalRxTurnScratch),
    );
    defer {
        scratch.lifecycle = .ready;
        _ = storage.releaseWholeTurnLease(&lease);
    }
    scratch.lifecycle = .busy;
    scratch.authority_ranges_generation = storage.operation_generation;

    const client = &storage.owned_client.?;
    const state = switch (client.io_mode) {
        .external => |*external| external,
        .blocking => return error.TestUnexpectedResult,
    };
    const bound_provenance = state.rx_provenance;
    var candidate_byte: u8 = 0;
    const candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(&candidate_byte),
        .len = 1,
    };

    var skipped = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const skipped_seal = try Helper.advance(&skipped, candidate);
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &skipped,
            .capture_before_cleanup,
            skipped_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = bound_provenance;

    var aborted = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const abort_seal = try Helper.advance(&aborted, candidate);
    try Helper.captureValidated(&aborted, abort_seal, candidate);
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_validate,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_before_cleanup,
            abort_seal,
            candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .validate_after_cleanup,
            abort_seal,
            candidate,
        ) == .accepted,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .validate_after_cleanup,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_cleanup_validate,
            abort_seal,
            candidate,
        ) == .seal,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &aborted,
            .capture_after_cleanup_validate,
            abort_seal,
            candidate,
        ) == .quarantined,
    );
    state.rx_provenance = bound_provenance;

    var abort_drift = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const drift_seal = try Helper.advance(&abort_drift, candidate);
    try Helper.captureValidated(&abort_drift, drift_seal, candidate);
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &abort_drift,
            .capture_before_cleanup,
            drift_seal,
            candidate,
        ) == .seal,
    );
    client.parser.expected_major +%= 1;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &abort_drift,
            .validate_after_cleanup,
            drift_seal,
            candidate,
        ) == .quarantined,
    );
    client.parser.expected_major -%= 1;
    state.rx_provenance = bound_provenance;

    try std.testing.expectEqual(@as(usize, 0), client.parser.buf.capacity);
    const replacement = try client.parser.allocator.alloc(u8, 1);
    defer client.parser.allocator.free(replacement);
    var committed = ProductReplacementAllocationGuard{
        .storage = &storage,
        .lease = &lease,
        .scratch = scratch,
        .admitted_len = 1,
    };
    const commit_candidate = client_external_mode.ReplacementCandidate{
        .addr = @intFromPtr(replacement.ptr),
        .len = replacement.len,
    };
    const commit_seal = try Helper.advance(&committed, commit_candidate);
    try Helper.captureValidated(&committed, commit_seal, commit_candidate);
    const source_buf = client.parser.buf;
    const source_head = client.parser.head;
    state.rx_provenance = .{ .lifecycle = .terminal };
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .capture_before_cleanup,
            commit_seal,
            null,
        ) == .seal,
    );
    client.parser.buf.items = replacement;
    client.parser.buf.capacity = replacement.len;
    client.parser.head = 0;
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .validate_after_cleanup,
            commit_seal,
            null,
        ) == .accepted,
    );
    try std.testing.expect(
        ProductReplacementAllocationGuard.check(
            &committed,
            .capture_after_cleanup_validate,
            commit_seal,
            null,
        ) == .seal,
    );
    client.parser.buf = source_buf;
    client.parser.head = source_head;
    state.rx_provenance = bound_provenance;
}

test "C4d injected zero-prefix would-block settles and publishes drain once" {
    const ApplyProbe = struct {
        apply_calls: *usize,

        fn apply(
            raw: *anyopaque,
            _: external_inbox_ledger.PayloadView,
        ) LiveScreenApplyResult {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.apply_calls.* += 1;
            return .applied;
        }
    };
    const Probe = struct {
        read_calls: usize = 0,
        apply_calls: usize = 0,

        fn read(
            raw: *anyopaque,
            _: posix.fd_t,
            _: []u8,
        ) client_external_rx_read.RxReadOutcome {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.read_calls += 1;
            return .would_block;
        }
    };

    var fixture = try TestClient.init();
    defer fixture.deinitPeer();
    var storage: ExternalPumpStorage = .{};
    try std.testing.expect(
        initTestStorage(&storage, &fixture.client, valid_evidence) ==
            .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    var fence_clear: projection_test.PreparedInitialFenceClear = .{};
    try std.testing.expect(projection_test.prepare(&storage, &fence_clear));
    try std.testing.expectEqual(
        projection_test.InitialFenceClearResult.cleared,
        projection_test.commit(&storage, &fence_clear),
    );
    defer _ = teardownForTest(&storage);

    const scratch = try std.testing.allocator.create(ExternalRxTurnScratch);
    defer std.testing.allocator.destroy(scratch);
    scratch.* = .{};
    try std.testing.expect(ExternalRxTurnScratch.initInPlace(scratch));
    var probe = Probe{};
    var apply_probe = ApplyProbe{ .apply_calls = &probe.apply_calls };
    const ops = RxTurnOps{
        .buffered = .{
            .context = &apply_probe,
            .context_len = @sizeOf(ApplyProbe),
            .apply_live_screen = ApplyProbe.apply,
        },
        .transport = .{
            .context = &probe,
            .context_len = @sizeOf(Probe),
            .read = Probe.read,
        },
    };
    var drain_recorder = RxDrainTestRecorder{};
    var authority_recorder = AuthorityAdapterTestRecorder{};
    rx_drain_test_recorder = &drain_recorder;
    authority_adapter_test_recorder = &authority_recorder;
    defer rx_drain_test_recorder = null;
    defer authority_adapter_test_recorder = null;
    const result = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 1 },
        &ops,
        scratch,
    );
    try std.testing.expect(result.terminal == null);
    try std.testing.expect(result.authority_clear);
    try std.testing.expectEqual(@as(usize, 1), probe.read_calls);
    try std.testing.expectEqual(@as(usize, 0), probe.apply_calls);
    try std.testing.expectEqual(@as(usize, 0), result.rx_read_bytes);
    try std.testing.expectEqual(@as(usize, 0), result.rx_bytes);
    try std.testing.expectEqual(@as(usize, 0), result.rx_frames);
    try std.testing.expectEqual(@as(u8, 3), drain_recorder.len);
    try std.testing.expectEqual(
        [_]RxDrainTestEvent{ .consumed, .published, .decide },
        drain_recorder.events,
    );
    rx_drain_test_recorder = null;
    authority_adapter_test_recorder = null;
    try std.testing.expectEqual(@as(u8, 4), authority_recorder.len);
    try std.testing.expectEqual(
        [_]AuthorityAdapterTestEvent{
            .prepared,
            .validated,
            .aborted,
            .reset,
        },
        authority_recorder.events,
    );
    try std.testing.expect(
        ExternalPumpStorage.authorityDestinationsPristine(scratch),
    );
    try std.testing.expectEqual(@as(u64, 2), scratch.turn_generation);
    try std.testing.expect(scratch.read.isReady());
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
        &scratch.drain_evidence,
    ));
    const first_generation = scratch.drain_evidence.read_attempt_generation;
    const first_operation_generation =
        scratch.drain_evidence.operation_generation;
    const first_digest = scratch.drain_evidence.digest;
    var stale_copy = scratch.drain_evidence;
    try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
        &stale_copy,
    ));

    const second = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 2 },
        &ops,
        scratch,
    );
    try std.testing.expect(second.terminal == null);
    try std.testing.expect(second.authority_clear);
    try std.testing.expectEqual(@as(usize, 2), probe.read_calls);
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
        &scratch.drain_evidence,
    ));
    try std.testing.expectEqual(
        first_generation,
        scratch.drain_evidence.read_attempt_generation,
    );
    try std.testing.expect(
        scratch.drain_evidence.operation_generation >
            first_operation_generation,
    );
    try std.testing.expect(!std.mem.eql(
        u8,
        &first_digest,
        &scratch.drain_evidence.digest,
    ));

    scratch.drain_evidence.lifecycle = .consumed;
    scratch.drain_evidence.digest =
        ExternalPumpStorage.drainEvidenceDigest(&scratch.drain_evidence);
    const before_callback_finish = scratch.drain_evidence;
    active_callback_region_addr = @intFromPtr(scratch);
    try std.testing.expect(!ExternalPumpStorage.armRxDrainEvidence(
        scratch,
        scratch.drain_evidence.read_attempt_generation,
    ));
    try std.testing.expect(!ExternalPumpStorage.finishRxDrainEvidence(scratch));
    active_callback_region_addr = 0;
    try std.testing.expect(std.meta.eql(
        before_callback_finish,
        scratch.drain_evidence,
    ));
    try std.testing.expect(ExternalPumpStorage.finishRxDrainEvidence(scratch));

    const pristine = scratch.drain_evidence;
    inline for ([_][]const u8{
        "storage_addr",
        "lease_generation",
        "parser_addr",
        "owner_inventory_generation",
        "receipt_addr",
        "seed_addr",
        "prepared_seed_authority_digest",
    }) |field_name| {
        if (comptime std.mem.eql(u8, field_name, "storage_addr"))
            scratch.drain_evidence.storage_addr +%= 1
        else if (comptime std.mem.eql(u8, field_name, "lease_generation"))
            scratch.drain_evidence.lease_generation +%= 1
        else if (comptime std.mem.eql(u8, field_name, "parser_addr"))
            scratch.drain_evidence.parser_addr +%= 1
        else if (comptime std.mem.eql(
            u8,
            field_name,
            "owner_inventory_generation",
        ))
            scratch.drain_evidence.owner_inventory_generation +%= 1
        else if (comptime std.mem.eql(u8, field_name, "receipt_addr"))
            scratch.drain_evidence.receipt_addr +%= 1
        else if (comptime std.mem.eql(u8, field_name, "seed_addr"))
            scratch.drain_evidence.seed_addr +%= 1
        else
            scratch.drain_evidence.prepared_seed_authority_digest[0] ^= 1;
        const corrupted = scratch.drain_evidence;
        try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
            &scratch.drain_evidence,
        ));
        try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
        try std.testing.expect(std.meta.eql(
            corrupted,
            scratch.drain_evidence,
        ));
        scratch.drain_evidence = pristine;
        try std.testing.expect(ExternalPumpStorage.rxDrainEvidenceSealed(
            &scratch.drain_evidence,
        ));
    }

    var foreign_storage = storage;
    const before_foreign_reset = scratch.drain_evidence;
    try std.testing.expect(
        !foreign_storage.resetFinishedRxDrainEvidence(scratch),
    );
    try std.testing.expect(std.meta.eql(
        before_foreign_reset,
        scratch.drain_evidence,
    ));
    var moved_scratch = scratch.*;
    const before_moved_reset = moved_scratch.drain_evidence;
    try std.testing.expect(
        !storage.resetFinishedRxDrainEvidence(&moved_scratch),
    );
    try std.testing.expect(std.meta.eql(
        before_moved_reset,
        moved_scratch.drain_evidence,
    ));

    try std.testing.expect(storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(rxDrainEvidencePristine(&scratch.drain_evidence));
    const reset_once = scratch.drain_evidence;
    try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(std.meta.eql(reset_once, scratch.drain_evidence));

    const third = storage.pumpRxTurn(
        .{ .readable = true, .writable = false, .now_ns = 3 },
        &ops,
        scratch,
    );
    try std.testing.expect(third.terminal == null);
    try std.testing.expect(third.authority_clear);
    try std.testing.expectEqual(@as(usize, 3), probe.read_calls);
    try std.testing.expectEqual(
        RxDrainEvidenceLifecycle.finished,
        scratch.drain_evidence.lifecycle,
    );
    try std.testing.expect(
        scratch.drain_evidence.operation_generation >
            first_operation_generation,
    );
    try std.testing.expect(!ExternalPumpStorage.rxDrainEvidenceSealed(
        &stale_copy,
    ));

    const evidence_before_reconstruction = scratch.drain_evidence;
    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
    storage = .{};
    var replacement_fixture = try TestClient.init();
    defer replacement_fixture.deinitPeer();
    try std.testing.expect(
        initTestStorageWithAttachInstanceForTest(
            &storage,
            &replacement_fixture.client,
            valid_evidence,
            .{ .test_skip_process_owner_reservation = true },
            2,
        ) == .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(std.meta.eql(
        evidence_before_reconstruction,
        scratch.drain_evidence,
    ));

    try std.testing.expectEqual(TeardownResult.cleaned, teardownForTest(&storage));
    storage = .{};
    var third_fixture = try TestClient.init();
    defer third_fixture.deinitPeer();
    try std.testing.expect(
        initTestStorageWithAttachInstanceForTest(
            &storage,
            &third_fixture.client,
            valid_evidence,
            .{ .test_skip_process_owner_reservation = true },
            3,
        ) == .initialized,
    );
    try std.testing.expect(prepareAdoptionForTest(&storage) == .prepared_adopted);
    try std.testing.expect(storage.commitAdoption() == .adopted);
    try std.testing.expect(!storage.resetFinishedRxDrainEvidence(scratch));
    try std.testing.expect(std.meta.eql(
        evidence_before_reconstruction,
        scratch.drain_evidence,
    ));
}

